const e="Law, JD / Public Health, MPH (Boston)",t={verified:!1,lastEdited:"9/9/2026",branch:"main",tablesPresent:0,tablesConsumed:0,tablesOnPage:0,tablesExcluded:0,sourceUrl:"https://catalog.northeastern.edu/graduate/law/dual-degrees/law-jd-public-health-mph/",panes:[""],planOfStudyCourses:[],verification:{level:"partial",kind:"grad",score:.83,checkedAt:"2026-09-10",sourceUrl:"https://catalog.northeastern.edu/graduate/law/dual-degrees/law-jd-public-health-mph/",sourcesAvailable:["requirement-tables","course-catalog"],counters:{tablesUnaccounted:0,leakedMarkers:0,unenumeratedSections:1,duplicateSectionTitles:0,duplicateConcentrationTitles:0,zeroTotal:1,unknownCourses:0,planUnexplained:0,impossibleSections:0},discrepancies:[{check:"missing-total-credits",severity:"medium",message:"the catalog page states no total credit requirement",detail:[{key:"noTotal"}],overflow:0},{check:"unenumerated-sections",severity:"info",message:"1 section(s) state a credit requirement whose courses the catalog does not list, so completion of those cannot be checked automatically",detail:[{key:"unenumeratedSection",params:{title:"2026-2027 Edition",sh:9}}],overflow:0}]}},o=0,a=2027,r=[{type:"SECTION",title:"2026-2027 Edition",creditsRequired:9,minRequirementCount:1,requirements:[],notes:["Northeastern University’s School of Law and Bouvé College of Health Sciences offer a JD/MPH dual degree. Given the worldwide trend toward urbanization, the Master of Public Health (MPH) recognizes the growing need for professionals trained to respond to unique public health challenges and opportunities facing urban populations. The MPH program brings together interdisciplinary faculty (from the School of Law, DʼAmore-McKim School of Business, College of Social Sciences and Humanities, Khoury College of Computer Sciences, and the Bouvé College of Health Sciences) with expertise in collaborating with diverse urban populations to offer students an opportunity to obtain practice-based knowledge, skills, and experience needed to address public health problems.","Up to 9 credit hours of coursework in the JD program may count toward the MPH, while up to 12 credit hours of coursework in the MPH program may count toward the JD. See the JD/MPH program page for more information.","All JD students, including FlexJD students, are ordinarily eligible to apply into dual degree pathways."]}],n={name:e,metadata:t,totalCreditsRequired:o,yearVersion:a,requirementSections:r};export{n as default,t as metadata,e as name,r as requirementSections,o as totalCreditsRequired,a as yearVersion};
